def calculate_a_large(limit):
    a = [0] * (limit + 1)
    a[1] = 1
    a[2] = 1
    for n in range(3, limit + 1):
        prev_a = a[n-1]
        a[n] = a[prev_a] + a[n - prev_a]
    return a

res = calculate_a_large(1000)
for i in range(1, 101):
    print(f"a_{i} = {res[i]}", end=', ')
    if i % 10 == 0: print()
